def rect(w, l):
    return w * l

def tri(b, h):
    return 0.5 * b * h

def circle(r):
    return 3.14 * r * r

k = int(input())
if k == 1:
    print(f"{rect(float(input()), float(input())):.2f}")
elif k == 2:
    print(f"{tri(float(input()), float(input())):.2f}")
elif k == 3:
    print(f"{circle(float(input())):.2f}")
else:
    print("ไม่มีรูปนี้")

def current(v, r):
    return v / r

v = float(input())
r = float(input())
if r <= 0:
    print("ข้อมูลผิดพลาด")
else:
    print(f"{current(v, r):.2f}")

def bmi_result(w, h_cm):
    if w <= 0 or h_cm <= 0:
        return "กรุณากรอกข้อมูลให้ถูกต้อง"
    bmi = w / (h_cm / 100) ** 2
    if bmi < 18.5:
        t = "ผอม"
    elif bmi < 23:
        t = "ปกติ"
    elif bmi < 25:
        t = "ท้วม"
    else:
        t = "อ้วน"
    return f"BMI {bmi:.2f} {t}"

w = float(input())
h = float(input())
print(bmi_result(w, h))
